mapper.delete:
delete from route_attractions
where route_id = #{routeId}
  and visit_order = #{visitOrder}

mapper.update:
update route_attractions
set poi_id = #{poiId},
    visit_time = #{visitTime},
    recommended_duration = #{recommendedDuration},
    notes = #{notes}
where route_id = #{routeId}
  and visit_order = #{visitOrder}

mapper.select:
select 
from route_attractions
where route_id = #{routeId}
  and visit_order = #{visitOrder}
